from pathlib import Path
import re
root=Path(__file__).resolve().parents[1]/'dist'
home=(root/'index.html').read_text()
header=home[home.index('  <div id="top">'):home.index('  <main id="main">')].replace('<h1 class="masthead-title">','<div class="masthead-title">').replace('</h1>','</div>')
footer=home[home.index('  <footer class="site-footer">'):home.index('    <script src=')]
def links(s):return re.sub(r'href="#([^"]*)"',lambda m:'href="index.html#'+m[1]+'"',s)
body='''<main class="futures-page" id="main"><section class="network-opening futures-shell"><p class="eyebrow">Civic Futures</p><h1>New connections.<br>Shared possibilities.</h1><div class="network-intro"><p>We help people organize and lead.</p><p>We connect students in Syria and abroad, support emerging civic leaders, and help people turn ideas into projects.</p></div></section>
<section class="network-feature futures-shell" id="in-practice"><figure><img src="assets/nsls/uploads/damascus-university-internal-view.jpg" alt="University campus in Damascus"><figcaption>Across campuses. Across borders.</figcaption></figure><div><p class="eyebrow">At the heart of Civic Futures</p><h2>The University<br>Network</h2><p>We’re building university chapters where students can work on shared questions, exchange ideas, and contribute to public debate. Our policy clinics in Syria bring students into the work of developing proposals.</p><a class="futures-link" href="#interest">Join the conversation ↗</a></div></section>
<section class="network-band"><div class="futures-shell"><p class="eyebrow">Students in Syria and abroad</p><h2>A campus can be<br>a starting point.</h2><p class="network-caption">Our network includes students at</p><div class="university-names"><span>Harvard</span><span>Yale</span><span>Princeton</span><span>Georgetown</span></div><div class="network-ways"><p>University chapters</p><p>Policy clinics</p><p>Exchange</p></div></div></section>
<section class="future-next futures-shell"><div class="future-next-heading"><p class="eyebrow">Also taking shape</p><h2>More ways to take part.</h2></div><div class="future-next-grid"><article><p class="eyebrow">In development</p><h3>Youth Fellows</h3><p>We’re developing a fellowship built around mentorship and practical support, helping young Syrians develop their ideas, build relationships, and take on public responsibilities.</p></article><article><p class="eyebrow">In development</p><h3>Civic Initiatives</h3><p>We’re creating a route for people to bring forward initiatives of their own, connecting their ideas with collaborators and the support needed to put them into practice.</p></article></div></section>
<section class="interest-band" id="interest"><div class="futures-shell interest-layout"><div><p class="eyebrow">Stay connected</p><h2>Follow what’s next.</h2><p>Hear about the work as it develops, or tell us how you’d like to contribute.</p></div><details class="interest-details"><summary>Get in touch &amp; register interest <span aria-hidden="true">↗</span></summary><form id="interest-form"><div class="field-pair"><label>Your name<input name="name" autocomplete="name" required maxlength="120"></label><label>Email address<input name="email" type="email" autocomplete="email" required maxlength="254"></label></div><fieldset><legend>What interests you? <span>(choose any)</span></legend><label class="check"><input type="checkbox" name="interest" value="University Network"> University Network</label><label class="check"><input type="checkbox" name="interest" value="Youth Fellows"> Youth Fellows</label><label class="check"><input type="checkbox" name="interest" value="Civic Initiatives"> Civic Initiatives</label><label class="check"><input type="checkbox" name="interest" value="General updates"> I’m still exploring</label></fieldset><label>University or organization <span>(optional)</span><input name="organization" autocomplete="organization" maxlength="200"></label><label>Anything you’d like to tell us? <span>(optional)</span><textarea name="message" rows="3" maxlength="2000" placeholder="An idea, a question, or how you’d like to take part."></textarea></label><label class="check consent"><input name="updates" type="checkbox"> I’d like emails from Syria Civic about Civic Futures opportunities and activities.</label><p class="interest-small">For now, send your interest by email. The button opens a draft for you to review and send; it does not subscribe you automatically.</p><button type="submit">Prepare my interest email <span aria-hidden="true">↗</span></button><p id="interest-status" role="status" aria-live="polite"></p><p class="interest-small">Prefer to write directly? <a href="mailto:info@syriacivic.com">info@syriacivic.com</a></p></form></details></div></section></main>'''
head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Civic Futures — Syria Civic</title><meta name="description" content="Explore Syria Civic’s university network, policy clinics, Youth Fellows, and civic initiatives."><link href="https://fonts.googleapis.com/css2?family=Source+Sans+3:wght@400;500;600;900&amp;family=Source+Serif+4:opsz,wght@8..60,400;600&amp;display=swap" rel="stylesheet"><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="futures.css?v=editorial20"><link rel="icon" type="image/png" href="assets/favicon.png"></head><body><a class="skip-link" href="#main">Skip to content</a>'''
(root/'civic-futures.html').write_text(head+links(header)+body+links(footer)+'<script src="script.js"></script><script src="futures.js"></script></body></html>')
